<script setup>
import { onMounted, reactive, ref } from 'vue';
import { galleryManager } from '../../services/galleryManagement.js';
import { galleryImages } from '../../data/gallery.js';
import { galleryCollectionExamples } from '../../data/galleryCollections.js';
const rows=ref([]),busy=ref(false),saving=ref(false),error=ref(''),message=ref(''),editing=ref(false),draft=reactive({}),listText=ref('');
function fresh(row={}) { Object.keys(draft).forEach(key=>delete draft[key]); Object.assign(draft,{id:'',title:'',description:'',cover_image_id:'',sort_order:0,published:true,...row});listText.value=(row.imageIds||[]).join('\n');editing.value=true; }
async function load(){busy.value=true;error.value='';try{rows.value=await galleryManager.collections({ownerOnly:true});}catch(cause){error.value=cause?.message||'合集读取失败，请检查迁移和权限。';}finally{busy.value=false;}}
async function save(){if(saving.value)return;saving.value=true;error.value='';try{const imageIds=listText.value.split(/[\s,，]+/u).filter(Boolean);await galleryManager.saveCollection(draft.id,{...draft,imageIds});message.value='合集已保存；图片可以同时加入多个合集。';editing.value=false;await load();}catch(cause){error.value=cause?.message||'保存失败，请重试。';}finally{saving.value=false;}}
async function remove(row){if(!confirm(`删除合集「${row.title}」？只删除组织关系，图片与收藏不会被删除。`))return;saving.value=true;try{await galleryManager.deleteCollection(row.id);message.value='已删除合集，图片仍保留。';await load();}catch(cause){error.value=cause?.message||'删除失败。';}finally{saving.value=false;}}
onMounted(load);
</script>
<template><section class="collection-manager"><h2>主题合集</h2><p>用雨夜、演出后台或四人合照串起收藏。一张图片可以加入多个合集；编号和来源均保持原样。</p><div class="collection-actions"><button type="button" @click="fresh()">新建合集</button><RouterLink to="/collections">查看公开合集 ↗</RouterLink><button type="button" :disabled="busy" @click="load">刷新</button></div><p v-if="busy" role="status">正在读取合集…</p><p v-if="error" role="alert" class="collection-error">{{error}}</p><p v-if="message" role="status">{{message}}</p><p v-if="!busy&&!error&&!rows.length">还没有云端合集。下面的两份本站策展仍可浏览。</p>
<ul class="collection-list"><li v-for="row in rows" :key="row.id"><strong>{{row.title}}</strong><span>{{row.imageIds.length}} 张 · {{row.published?'公开':'未公开'}} · 顺序 {{row.sort_order}}</span><div class="collection-actions"><button type="button" :disabled="saving" @click="fresh(row)">编辑</button><button type="button" :disabled="saving" @click="remove(row)">删除合集</button><RouterLink :to="`/collections/${row.id}`">查看</RouterLink></div></li></ul>
<form v-if="editing" class="collection-form" @submit.prevent="save"><label>合集标题<input v-model="draft.title" maxlength="80" required></label><label>简介<textarea v-model="draft.description" maxlength="600" rows="3"></textarea></label><label>图片编号（每行一个，按展示顺序排列）<textarea v-model="listText" rows="6" placeholder="collection-20261029-19&#10;cloud-图片 UUID"></textarea></label><p>直接复制已发布列表中的完整图片编号（包括 cloud- 前缀）。也可从下方静态素材参考中复制编号。未公开或不存在的图片不会在公开页面展示。</p><details><summary>静态素材编号参考</summary><ul class="id-reference"><li v-for="image in galleryImages" :key="image.id">{{image.title}} <code>{{image.id}}</code></li></ul></details><label>封面图片编号（留空使用首张）<input v-model="draft.cover_image_id" maxlength="96"></label><label>展示顺序<input v-model.number="draft.sort_order" type="number" min="-1000000" max="1000000" step="1"></label><label class="published-checkbox"><input v-model="draft.published" type="checkbox">在公开合集页展示</label><div class="collection-actions"><button :disabled="saving">{{saving?'正在保存…':'保存合集'}}</button><button type="button" :disabled="saving" @click="editing=false">取消</button></div></form>
<h3>本站策展（仓库静态内容）</h3><ul class="collection-list"><li v-for="row in galleryCollectionExamples" :key="row.id"><strong>{{row.title}}</strong><span>{{row.imageIds.length}} 张 · 需在代码仓库维护</span><RouterLink :to="`/collections/${row.id}`">查看合集 ↗</RouterLink></li></ul></section></template>
<style scoped>
.collection-manager h2{font-size:25px}.collection-manager p{font-size:13px;line-height:1.8}.collection-actions{display:flex;align-items:center;flex-wrap:wrap;gap:12px;margin:16px 0}button,a{display:inline-flex;align-items:center;min-height:44px;padding:10px 15px;font-size:14px}button{background:#663e55;color:#fff8ee;border:1px solid #663e55;cursor:pointer}button:disabled{opacity:.5}a{color:#773f5c;text-decoration:underline}.collection-list{list-style:none;padding:0;display:grid;gap:12px}.collection-list>li{padding:18px;border:1px solid #ceb6bf;background:#fff8ef;display:grid;gap:10px}.collection-list span{font-size:13px;color:#755f70}.collection-form{padding:22px;background:#eddfd7;display:grid;gap:16px}.collection-form label{display:grid;gap:8px;font-weight:700;font-size:14px}.collection-form :is(input,textarea){min-height:44px;min-width:0;width:100%;padding:10px;border:1px solid #b8a491;background:#fffcf5;color:#493b47;font:inherit;font-size:16px}.collection-form .published-checkbox{display:flex;align-items:center;min-height:44px;gap:10px}.published-checkbox input{width:22px;height:22px;min-height:22px}.collection-error{color:#9b2449}.id-reference{max-height:260px;overflow:auto;padding:0;list-style:none}.id-reference li{display:grid;gap:5px;padding:10px 0;font-size:13px}.id-reference code{user-select:all;overflow-wrap:anywhere}.collection-form summary{min-height:44px;cursor:pointer}
</style>
